    const vpack=(W.a11y&&W.a11y.guideVoices)?W.a11y.guideVoices():{total:0,zh:0,guide:false};
    h+='<div class="card"><div class="tagline">视 图 · 清 爽</div>'
      +'<div class="mini">设置已改成独立抽屉：顶部大按钮随时关闭返回，'
